INSERT INTO facilities (
    id, tenant_id, farm_id, code, name, facility_type, status, capacity, capacity_unit, supervisor_name
)
SELECT gen_random_uuid(), f.tenant_id, f.id, f.code || '-' || kinds.code, f.name || ' ' || kinds.name,
       kinds.facility_type, 'ACTIVE', kinds.capacity, kinds.unit, f.manager_name
FROM farms f
CROSS JOIN (
    VALUES
        ('GRZ', 'Grazing', 'GRAZING', 800, 'head'),
        ('BRN', 'Barn', 'BARN', 200, 'head'),
        ('PEN', 'Pen', 'PEN', 80, 'head'),
        ('STR', 'Store', 'WAREHOUSE', 40, 'tonne')
) AS kinds(code, name, facility_type, capacity, unit)
WHERE NOT (f.id = 'a1000008-0000-4000-8000-000000000008' AND kinds.code = 'STR');

