INSERT INTO movement_events (
    id, tenant_id, event_type, subject_type, subject_id, farm_id, quantity,
    effective_at, actor_id, reason, idempotency_key
)
SELECT gen_random_uuid(), b.tenant_id, 'REGISTRATION', 'BATCH', b.id, b.farm_id, b.quantity,
       b.created_at, '22222222-2222-4222-8222-222222222222', 'Opening herd balance', 'seed-batch-' || b.code
FROM batches b;

INSERT INTO movement_events (
    id, tenant_id, event_type, subject_type, subject_id, farm_id, quantity,
    effective_at, actor_id, reason, idempotency_key
)
SELECT gen_random_uuid(), a.tenant_id, 'REGISTRATION', 'ANIMAL', a.id, a.farm_id, 1,
       a.created_at, '22222222-2222-4222-8222-222222222222', 'Individual registration', 'seed-animal-' || a.tag
FROM animals a;

